import json
from collections import Counter

def _parse_grid(obs: str):
    """Extract the 2D colour grid as list[list[str]] (rows of colour-name strings).

    Anchor on the generic '[[' / ']]' so it works regardless of the header text that precedes
    the grid. Do NOT gate on the observation *starting* with '[[': Autumn observations are
    prefixed by a "Task:/Step:/..." header, so the grid begins mid-string. Returns None on
    failure (caller degrades gracefully, never raises)."""
    if not obs:
        return None
    start = obs.find("[[")
    end = obs.rfind("]]")
    if start == -1 or end == -1 or end < start:
        return None
    try:
        grid = json.loads(obs[start : end + 2])
    except Exception:
        return None
    if not grid or not isinstance(grid, list) or not isinstance(grid[0], list):
        return None
    return grid

def _find_background(grid):
    """Return the colour that appears most frequently in the grid (the background)."""
    flat = [cell for row in grid for cell in row]
    if not flat:
        return "black"  # fallback
    counter = Counter(flat)
    # most_common returns list of (value, count) sorted descending
    return counter.most_common(1)[0][0]

def perceive(observation_history: list[str]) -> str:
    obs = observation_history[-1] if observation_history else ""
    grid = _parse_grid(obs)
    if grid is None:
        return "grid_parse_error"

    background = _find_background(grid)

    # Collect non-background cells with absolute coordinates
    cells = []
    for r, row in enumerate(grid):
        for c, colour in enumerate(row):
            if colour != background:
                cells.append((r, c, colour))

    if not cells:
        return "no_foreground"

    # Build a concise summary: sorted by row then column
    cells.sort()
    parts = [f"{r},{c}:{colour}" for r, c, colour in cells]
    summary = ";".join(parts)

    # Ensure it does not exceed 2000 characters (truncate if necessary, but keep whole entries)
    # We try to keep all, but in case of overflow we cut at a safe boundary.
    if len(summary) > 2000:
        # Keep as many full entries as possible
        # Truncate at the last ';' before 2000
        cutoff = summary[:1999].rfind(';')
        if cutoff > 0:
            summary = summary[:cutoff] + "..."
        else:
            summary = summary[:1997] + "..."

    return summary
